#requires -Version 7.1
<#
.SYNOPSIS
Executes finite explicitly selected lifecycle actions for one selected Android app/device.
.PARAMETER Tasks
Background uses a trusted own-app adapter, or AllowHomeBackground after foreground verification. Resume launches only the selected component. ProcessRecreate explicitly force-stops/relaunches the selected package: this is not a natural OS kill. Rotation requires the app-owned adapter; global settings are never changed.
.PARAMETER Component
Selected-package component using letters, digits, underscores and dots only. Dollar-sign nested Java class names are outside this shell-safe interface and are refused before any command; use an app-owned bridge for unsupported component forms.
.PARAMETER AdapterPath
Optional trusted local native bridge to an app-owned adapter. JSON stdin request {schemaVersion:1,deviceSerial,packageName,action}; stdout response {schemaVersion:1,packageName,action,passed:boolean,values?:object}. Actions Background, Rotation, Persistence. ExecuteTrustedAdapter acknowledges execution. Bridge is responsible for selected app-only implementation; it is not a sandbox.
.PARAMETER PersistencePath
Schema1 {schemaVersion:1,assertions:[{id,key,expected}]}; compares each expected JSON value in adapter Persistence values before and after all actions. Keys are case-sensitive. No root/run-as/filesystem dumps.
.NOTES
No install/uninstall/clear-data/global rotation or other-app kills. At most four distinct tasks, 1 MiB output/command and 1-30 second commands. Fake tests do not establish real device behavior.
#>
[CmdletBinding()]
param([Parameter(Mandatory)][ValidatePattern('^[A-Za-z0-9._:-]{1,128}$')][string]$DeviceSerial,[Parameter(Mandatory)][ValidatePattern('^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$')][string]$PackageName,[Parameter(Mandatory)][string]$Component,[Parameter(Mandatory)][ValidateSet('Background','Resume','ProcessRecreate','Rotation')][string[]]$Tasks,[Parameter(Mandatory)][string]$Destination,[Parameter(Mandatory)][string]$AdbPath,[string]$AdapterPath,[string[]]$AdapterArguments=@(),[switch]$ExecuteTrustedAdapter,[switch]$AllowHomeBackground,[string]$PersistencePath,[ValidateRange(1,30)][int]$TimeoutSeconds=15,[switch]$Json)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'lib/QualityGames.ps1');$r=QG-Result 'Invoke-AndroidLifecycle' @{deviceSerial=$DeviceSerial;packageName=$PackageName;tasks=$Tasks};$code=125;$dest=$null
try{
 if($Component -cnotmatch ('^'+[regex]::Escape($PackageName)+'/\.?[A-Za-z][A-Za-z0-9_.]*$')){throw 'Component must belong to the selected package and use the documented shell-safe grammar (no dollar signs).'};if($Tasks.Count -lt 1 -or $Tasks.Count -gt 4 -or @($Tasks|Select-Object -Unique).Count -ne $Tasks.Count){throw 'One to four distinct explicit tasks required.'};foreach($task in $Tasks){if($task -cnotin @('Background','Resume','ProcessRecreate','Rotation')){throw 'Task case must match documented interface.'}}
 $adb=QG-Exe $AdbPath;$new=QG-Path $Destination -New;$bridge=$null;if($AdapterPath){if(-not $ExecuteTrustedAdapter){throw 'ExecuteTrustedAdapter required.'};$bridge=QG-Exe $AdapterPath};if($AdapterArguments.Count -gt 64 -or @($AdapterArguments|Where-Object{$null -eq $_ -or $_.Length -gt 4096}).Count){throw 'Adapter arguments exceed bounds.'}
 $checks=$null;if($PersistencePath){if(-not $bridge){throw 'Persistence assertions require an explicitly trusted app-owned adapter.'};$checks=QG-Read $PersistencePath;QG-Fields $checks @('schemaVersion','assertions');QG-Schema $checks;if($checks.assertions -isnot [array] -or $checks.assertions.Count -lt 1 -or $checks.assertions.Count -gt 256){throw 'Nonempty bounded persistence assertions required.'};$ids=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($a in $checks.assertions){QG-Fields $a @('id','key','expected');if($a.id -isnot [string] -or $a.id -cnotmatch '^[A-Za-z][A-Za-z0-9_.-]{0,63}$' -or -not $ids.Add($a.id) -or $a.key -isnot [string] -or $a.key.Length -lt 1 -or $a.key.Length -gt 128){throw 'Invalid persistence assertion.'}}}
 if(('Rotation' -cin $Tasks -or ('Background' -cin $Tasks -and -not $AllowHomeBackground)) -and -not $bridge){$code=3;throw 'Requested task requires an app-owned adapter; no device operation performed.'}
 $null=[IO.Directory]::CreateDirectory($new);$dest=$new;$script:qgCommandIndex=0
 function Record-Command([string]$Exe,[string[]]$Arguments,[string]$InputText=''){$cmd=QG-Run $Exe $Arguments $InputText $TimeoutSeconds $dest;$script:qgCommandIndex++;$r.executionEvidence+=@{sequence=$script:qgCommandIndex;pid=$cmd.Pid;exitCode=$cmd.ExitCode;timedOut=$cmd.TimedOut;truncated=$cmd.Truncated};foreach($stream in @('Output','Error')){$p=Join-Path $dest "$($script:qgCommandIndex)-$stream.txt";[IO.File]::WriteAllText($p,$cmd.$stream);$r.artifacts+=QG-Artifact $p};if($cmd.TimedOut -or $cmd.Truncated){$script:qgFailureCode=3;throw 'Selected command exceeded time/output bound.'};if($cmd.ExitCode -ne 0 -or $cmd.Output -match '(?im)^\s*(Error\b|Failure\b|Exception\b)' -or $cmd.Error -match '(?im)^\s*(error\b|adb: error)'){$script:qgFailureCode=2;throw 'Selected command failed; inspect retained output.'};$cmd.Output}
 function Adb([string[]]$Command){Record-Command $adb (@('-s',$DeviceSerial)+$Command)}
 function App-Action([string]$Action){$request=@{schemaVersion=1;deviceSerial=$DeviceSerial;packageName=$PackageName;action=$Action}|ConvertTo-Json -Compress;$text=Record-Command $bridge $AdapterArguments $request;try{$o=QG-JsonText $text;QG-Fields $o @('schemaVersion','packageName','action','passed') @('values');QG-Schema $o;if($o.packageName -cne $PackageName -or $o.action -cne $Action -or $o.passed -isnot [bool]){throw 'Adapter target/action/type mismatch.'};if(-not $o.passed){$script:qgFailureCode=2;throw 'App-owned adapter reported failure.'};if($Action -ceq 'Persistence' -and (-not $o.Contains('values') -or $o.values -isnot [Collections.IDictionary])){throw 'Persistence values missing.'};return ,$o}catch{if($script:qgFailureCode -ne 2){$script:qgFailureCode=3};throw}}
 function Persistence([string]$Phase){$snapshot=App-Action 'Persistence';foreach($a in $checks.assertions){if($a.key -cnotin @($snapshot.values.Keys)){QG-Finding $r "$Phase/$($a.id)" 'Fail' 'Persistence key absent';$script:qgFailureCode=2;throw 'Persistence assertion failed.'};$actual=[DevTools.QualityGames.Data]::Canonical(($snapshot.values[$a.key]|ConvertTo-Json -Depth 32 -Compress));$expected=[DevTools.QualityGames.Data]::Canonical(($a.expected|ConvertTo-Json -Depth 32 -Compress));if($actual -cne $expected){QG-Finding $r "$Phase/$($a.id)" 'Fail' 'Persistence value mismatch';$script:qgFailureCode=2;throw 'Persistence assertion failed.'};QG-Finding $r "$Phase/$($a.id)" 'Pass' 'Configured value matches'}}
 function Launch{$text=Adb @('shell','am','start','-W','-n',$Component);if($text -notmatch '(?im)^Status:\s*ok\s*$' -or $text -match '(?im)^Status:\s*(?!ok\s*$)\S+'){$script:qgFailureCode=3;throw 'Activity start lacks successful semantic Status: ok.'}}
 $script:qgFailureCode=125;$state=Adb @('get-state');if($state.Trim() -cne 'device'){$script:qgFailureCode=3;throw 'Selected device is not ready.'};if($checks){Persistence 'before'}
 foreach($task in $Tasks){switch -CaseSensitive ($task){
  'Background'{if($bridge){$null=App-Action 'Background'}else{$foreground=Adb @('shell','dumpsys','activity','activities');$matches=[regex]::Matches($foreground,'(?m)^\s*(?:mResumedActivity|topResumedActivity):\s+ActivityRecord\{[^\r\n]*?\su\d+\s+([^\s/]+)/[^\s}]+');if($matches.Count -ne 1 -or $matches[0].Groups[1].Value -cne $PackageName){$script:qgFailureCode=3;throw 'HOME refused: selected own app not uniquely verified foreground.'};$null=Adb @('shell','input','keyevent','KEYCODE_HOME')}}
  'Resume'{Launch}
  'ProcessRecreate'{$null=Adb @('shell','am','force-stop',$PackageName);Launch}
  'Rotation'{$null=App-Action 'Rotation'}
 };QG-Finding $r $task 'Pass' $(if($task -ceq 'ProcessRecreate'){'Selected package force-stop/relaunch completed; natural OS kill NotPerformed'}else{'Requested action completed according to selected command/adapter evidence'})}
 if($checks){Persistence 'after'};$code=0;$r.limitations=@('Real device execution depends on explicitly selected ADB/adapter; fixture tests are synthetic.','ProcessRecreate is force-stop/relaunch, not natural OS process death or full lifecycle certification.','Persistence verifies only configured app-owned values; adapter evidence is not independently inspected app storage.','No installations, clear-data, root/run-as, global rotation or other-package termination.')
}catch{$r.error=$_.Exception.Message;if(Get-Variable qgFailureCode -Scope Script -ErrorAction SilentlyContinue){$code=$script:qgFailureCode}};QG-Finish $r $code -Json:$Json -Destination $dest
